window.FM_DATA["editortools"] = {"id":"editortools","title":"Editor Tools","entries":[{"id":"level-transform-guidance","name":"LevelTransformGuidance","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LevelTransformGuidanceWindow.cs","src_lines":[28,101],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Level Transform Guidance"]},"src_typeComment":"Toolkit/Level Transform Guidance — a HUB for level-design tools, one tab per tool.  Why a hub: level design is a mode of working, not a single action. Measuring a gap, checking a prop isn't sunk into the stairs, and stepping back to see whether a wing of the level is under-dressed all happen in the same sitting — one tabbed window matches that flow where three separate menu items fight it, and it lets the tools share plumbing (unit conversion, layer filtering, Scene-view drawing).  Tabs, and the distinct question each answers: - Clipping       — per-object correctness: \"is this one thing placed wrong?\" - Heatmap        — whole-level distribution: \"is my level evenly built?\" (doubles as a measuring grid) - Measuring Tape — a specific dimension: \"how far apart are these two points?\"  Two rules this window enforces, both to keep the hub from becoming overhead or clutter: 1. ONLY THE ACTIVE TAB is subscribed to anything. Switching tabs deactivates the old one and activates the new one; closing the window deactivates everything. Otherwise the Measuring Tape's click handling would fight the Clipping tab's highlight drawing, and you'd pay for tools you aren't looking at. 2. Each tab renders ONLY its own settings. Tabs exist to reduce visible complexity, not relocate it.  Guidance, deliberately, not Validator: every tab surfaces information for your judgement rather than making the call itself. The clipping check refuses to guess intent; the heatmap shows density and lets you decide whether it's wrong.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<LevelTransformGuidanceWindow>(\"Level Transform Guidance\")","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Toolkit/Level Transform Guidance — a HUB for level-design tools, one tab per tool.","src_uses":["ILtgTab","LtgClippingTab","LtgHeatmapTab","LtgMeasuringTapeTab","LtgSnapToMouseTab"],"src_usedBy":[],"src_extensionPoints":[],"isSystem":true,"systemOf":"LevelTransformGuidanceWindow","systemPrimaryId":"level-transform-guidance-window","systemSections":[{"title":"Window & tab framework","entries":[{"id":"i-ltg-tab","name":"ILtgTab","cat":"EditorTools","src_typeKind":"interface","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/ILtgTab.cs","src_lines":[11,30],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"One tool inside the Level Transform Guidance hub.  Activate/Deactivate exist because of a hard requirement: ONLY THE ACTIVE TAB may subscribe to Scene-view callbacks or handle Scene-view input. The Measuring Tape tab consumes left/middle clicks to place and clear points, while the Clipping tab draws depth-tested highlights every camera render — if both were live at once they'd fight each other, and the level designer would be paying for tools they aren't looking at. The hub calls Deactivate on the outgoing tab and Activate on the incoming one, and Deactivate on every tab when the window closes.","src_serialized":[],"src_members":[{"id":"Title","sig":"string Title { get; }","kind":"property","name":"Title","static":false,"comment":null},{"id":"IconName","sig":"string IconName { get; }","kind":"property","name":"IconName","static":false,"comment":"A built-in Unity editor icon name for the tab button (PLACEHOLDERS for now — swap for custom art later by dropping textures in and resolving them here instead). The window falls back to the Title text if the name doesn't resolve, since built-in icon names are undocumented and can differ between Unity versions — a wrong name must never produce a blank, unclickable tab."},{"id":"Activate()","sig":"void Activate()","kind":"method","name":"Activate","static":false,"comment":"Subscribe to Scene-view/editor callbacks here, not in a constructor."},{"id":"Deactivate()","sig":"void Deactivate()","kind":"method","name":"Deactivate","static":false,"comment":"Unsubscribe and drop any Scene-view visuals — the Scene view must return to clean."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"One tool inside the Level Transform Guidance hub.","src_uses":[],"src_usedBy":["ClippingDisplayMode","ClippingHighlightStyle","FixedPlaneAxis","LevelTransformGuidanceWindow","LtgClippingTab","LtgHeatmapTab","LtgMeasuringTapeTab","LtgSnapToMouseTab"],"src_extensionPoints":[]},{"id":"ltg-gui-utility","name":"LtgGuiUtility","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgGuiUtility.cs","src_lines":[7,16],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Small shared GUI helpers for the Level Transform Guidance hub's tabs.","src_serialized":[],"src_members":[{"id":"LayerMaskField(string, LayerMask)","sig":"public static LayerMask LayerMaskField(string label, LayerMask layerMask)","kind":"method","name":"LayerMaskField","static":true,"comment":"EditorGUILayout.MaskField mangles a LayerMask's raw value (it re-indexes to only the NAMED layers), so this converts through Unity's own helpers instead of assigning the field value directly."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Small shared GUI helpers for the Level Transform Guidance hub's tabs.","src_uses":[],"src_usedBy":["ClippingDisplayMode","ClippingHighlightStyle","LtgClippingTab","LtgHeatmapTab","LtgSnapToMouseTab"],"src_extensionPoints":[]}]},{"title":"Heatmap","entries":[{"id":"ltg-heatmap-tab","name":"LtgHeatmapTab","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgHeatmapTab.cs","src_lines":[24,292],"src_base":null,"src_implements":["ILtgTab"],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Heatmap tab: a density grid laid over a REGION of the level. Answers a whole-level distribution question — \"is my level evenly built?\" — as opposed to the Clipping tab's per-object correctness question. Over-decorated areas and barren dead zones are near-impossible to notice while zoomed in placing individual props, and both matter: barren patches read as unfinished, dense clusters hurt readability and are where draw calls concentrate.  The grid is a MOVABLE, SIZED region (centre + X/Y/Z), dragged with a Scene-view handle — you position it over the area you're inspecting instead of guessing at extents, and the region's Y size doubles as the height slice for stacked levels. The whole rectangle is always drawn, empty cells included, so it reads as one continuous grid.  It does DOUBLE DUTY on purpose: cell size is entered in a unit you choose (shared with the Measuring Tape tab), so a corridor spanning three 2-metre cells reads as 6 metres wide without measuring.  Performance discipline (standing requirement for every tab in this hub): the grid is CACHED and only rebuilt on demand or when the hierarchy actually changes — never per repaint, and it never forces continuous Scene-view repaints.","src_serialized":[],"src_members":[{"id":"Title","sig":"public string Title => \"Heatmap\"","kind":"property","name":"Title","static":false,"comment":null},{"id":"IconName","sig":"public string IconName => \"d_GridLayoutGroup Icon\"","kind":"property","name":"IconName","static":false,"comment":null},{"id":"Activate()","sig":"public void Activate()","kind":"method","name":"Activate","static":false,"comment":null},{"id":"Deactivate()","sig":"public void Deactivate()","kind":"method","name":"Deactivate","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Heatmap tab: a movable density grid over a region of the level, doubling as a measuring grid.","overview":["The Heatmap Grid's tab UI. Owns the region box and its Scene-view handle, and asks HeatmapGrid to do the counting. Settings and gotchas are documented on LevelTransformGuidance."],"src_uses":["Grid<T>","HeatmapCell","HeatmapGrid","HeatmapMetric","ILtgTab","LtgGuiUtility","MeasurementUnit","MeasurementUnits"],"src_usedBy":["LevelTransformGuidanceWindow"],"src_extensionPoints":[]},{"id":"heatmap-grid","name":"HeatmapGrid","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/HeatmapGrid.cs","src_lines":[45,199],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"The computation half of the Heatmap tab, kept free of any Scene-view/GUI dependency so it's directly testable: given a region and a cell size, produce a COMPLETE grid of cells with their density values.  Design decisions worth knowing: - The grid is defined by a movable REGION (centre + X/Y/Z size), not inferred from where objects happen to be. So the grid is always a full, continuous rectangle you position over the area you're inspecting — and the region's Y size doubles as the height slice, which is why there's no separate height-range setting. - EVERY cell in the region is returned, including empty ones, so the overlay reads as one continuous grid rather than floating islands of colour. - An object counts if it has a Renderer OR a Collider — bare GameObjects, empties and pivots are ignored, since they aren't \"level content\". - An object affects EVERY cell its bounds overlap horizontally, since level geometry isn't grid-aligned and a crate straddling two cells really does occupy both. ObjectCount therefore counts it in each overlapped cell, while BoundsVolume SPLITS its volume across them by footprint share (so the grid's total volume still equals the real total). The height slice still uses the bounds CENTRE, so an object belongs to exactly one storey.","src_serialized":[],"src_members":[{"id":"MaxCells","sig":"public const int MaxCells = 10000","kind":"const","name":"MaxCells","static":false,"comment":"Guard against a huge region with a tiny cell size asking for millions of quads — exactly the editor overhead this hub is meant to avoid."},{"id":"ColumnCount(float, float)","sig":"public static int ColumnCount(float sizeX, float cellSize) => Mathf.Max(1, Mathf.CeilToInt(sizeX / Mathf.Max(0.01f, cellSize)))","kind":"method","name":"ColumnCount","static":true,"comment":null},{"id":"RowCount(float, float)","sig":"public static int RowCount(float sizeZ, float cellSize) => Mathf.Max(1, Mathf.CeilToInt(sizeZ / Mathf.Max(0.01f, cellSize)))","kind":"method","name":"RowCount","static":true,"comment":null},{"id":"GridPlaneY(Vector3, Vector3)","sig":"public static float GridPlaneY(Vector3 regionCenter, Vector3 regionSize) => regionCenter.y - regionSize.y * 0.5f","kind":"method","name":"GridPlaneY","static":true,"comment":"The grid plane sits at the BOTTOM of the region, so positioning the box over a floor puts the grid on that floor rather than floating at its middle."},{"id":"CellCenter(int, int, Vector3, Vector3, float)","sig":"public static Vector3 CellCenter(int column, int row, Vector3 regionCenter, Vector3 regionSize, float cellSize)","kind":"method","name":"CellCenter","static":true,"comment":null},{"id":"Build(IEnumerable<GameObject>, Vector3, Vector3, float, LayerMask, HeatmapMetric, out float)","sig":"public static List<HeatmapCell> Build(IEnumerable<GameObject> objects, Vector3 regionCenter, Vector3 regionSize, float cellSize, LayerMask layerMask, HeatmapMetric metric, out float actualMaxValue)","kind":"method","name":"Build","static":true,"comment":null},{"id":"OverlapArea(Bounds, int, int, float, float, float)","sig":"public static float OverlapArea(Bounds bounds, int column, int row, float minX, float minZ, float cellSize)","kind":"method","name":"OverlapArea","static":true,"comment":"XZ area shared between an object's bounds and one cell — the weight used to split its volume."},{"id":"TryGetBounds(GameObject, out Bounds)","sig":"public static bool TryGetBounds(GameObject go, out Bounds bounds)","kind":"method","name":"TryGetBounds","static":true,"comment":"Renderer bounds preferred (that's the visual footprint, which is what \"visually heavy\" means); falls back to collider bounds for objects that collide but don't render."},{"id":"ColorFor(float, float, float)","sig":"public static Color ColorFor(float value, float densityMax, float alpha)","kind":"method","name":"ColorFor","static":true,"comment":"Green (sparse) -> yellow -> red (dense), normalised against an EXPLICIT densityMax rather than whatever the busiest cell happens to hold. Auto-scaling to the scene's own maximum meant a level containing a single object painted that cell fully red, which said nothing useful — with a fixed scale, \"red\" means a density YOU chose and stays comparable between scenes.  Routed through yellow rather than lerping green straight to red, because a direct lerp passes through a muddy brown at the midpoint that's genuinely hard to read against level geometry."}],"src_enumValues":[],"src_selfTest":"EditorTools/LevelTransformGuidance/Editor/HeatmapGridSelfTest.cs","src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"The computation half of the Heatmap tab, kept free of any Scene-view/GUI dependency so it's directly testable: given a...","src_uses":["HeatmapCell","HeatmapMetric"],"src_usedBy":["HeatmapCell","HeatmapMetric","LtgHeatmapTab"],"src_extensionPoints":[],"parts":[{"id":"heatmap-cell","name":"HeatmapCell","cat":"EditorTools","src_typeKind":"struct","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/HeatmapGrid.cs","src_lines":[17,26],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"column","sig":"public int column","kind":"field","name":"column","static":false,"comment":null},{"id":"row","sig":"public int row","kind":"field","name":"row","static":false,"comment":null},{"id":"center","sig":"public Vector3 center; // world-space centre of the cell, on the grid plane","kind":"field","name":"center","static":false,"comment":null},{"id":"objectCount","sig":"public int objectCount","kind":"field","name":"objectCount","static":false,"comment":null},{"id":"boundsVolume","sig":"public float boundsVolume","kind":"field","name":"boundsVolume","static":false,"comment":null},{"id":"ValueFor(HeatmapMetric)","sig":"public float ValueFor(HeatmapMetric metric) => metric == HeatmapMetric.ObjectCount ? objectCount : boundsVolume","kind":"method","name":"ValueFor","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["HeatmapGrid","HeatmapMetric"],"src_usedBy":["HeatmapGrid","HeatmapMetric","LtgHeatmapTab"],"src_extensionPoints":[],"foldedInto":"heatmap-grid"},{"id":"heatmap-metric","name":"HeatmapMetric","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/HeatmapGrid.cs","src_lines":[7,15],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"What the cell colour actually measures.","src_serialized":[],"src_members":[],"src_enumValues":["BoundsVolume","ObjectCount"],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"What the cell colour actually measures.","src_uses":["HeatmapCell","HeatmapGrid"],"src_usedBy":["HeatmapCell","HeatmapGrid","LtgHeatmapTab"],"src_extensionPoints":[],"foldedInto":"heatmap-grid"}]}]},{"title":"Clipping","entries":[{"id":"ltg-clipping-tab","name":"LtgClippingTab","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgClippingTab.cs","src_lines":[28,196],"src_base":null,"src_implements":["ILtgTab"],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Clipping tab: spots objects intersecting each other when they shouldn't. Answers a PER-OBJECT CORRECTNESS question (\"is this one thing placed wrong?\"), which is why it's a separate tab from the Heatmap's whole-level distribution question rather than a mode inside it.  Built around one honest limitation: NOTHING can tell whether an intersection was intended, so this never claims to. It finds candidates cheaply, paints what's actually buried, and leaves the call to you.  Subjects vs Targets: only SUBJECTS get painted, so floors/architecture never light up — you see the crate reddened where it's buried, not the floor it's buried in.","src_serialized":[],"src_members":[{"id":"Title","sig":"public string Title => \"Clipping\"","kind":"property","name":"Title","static":false,"comment":null},{"id":"IconName","sig":"public string IconName => \"d_console.warnicon\"","kind":"property","name":"IconName","static":false,"comment":null},{"id":"Activate()","sig":"public void Activate() => Camera.onPostRender += OnCameraPostRender","kind":"method","name":"Activate","static":false,"comment":"Drawn from Camera.onPostRender rather than a Scene-view GUI callback: the buried-portion pass needs the scene's real depth buffer still bound to ZTest against, and onPostRender fires immediately after a camera finishes rendering (target + depth intact)."},{"id":"Deactivate()","sig":"public void Deactivate()","kind":"method","name":"Deactivate","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Clipping tab: scans for objects sunk into each other and paints the buried part.","overview":["The Clipping Inspector's tab UI. Drives the scan, owns its settings, and asks ClippingCandidateFinder for candidates and ClippingHighlightRenderer to paint them. Settings and gotchas are documented on LevelTransformGuidance."],"src_uses":["ClippingCandidate","ClippingCandidateFinder","ClippingDisplayMode","ClippingHighlightRenderer","ClippingHighlightStyle","ILtgTab","LtgGuiUtility"],"src_usedBy":["ClippingDisplayMode","ClippingHighlightStyle","LevelTransformGuidanceWindow"],"src_extensionPoints":[],"parts":[{"id":"clipping-display-mode","name":"ClippingDisplayMode","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgClippingTab.cs","src_lines":[7,11],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["Collider","Mesh"],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["ClippingCandidate","ClippingCandidateFinder","ClippingHighlightRenderer","ClippingHighlightStyle","ILtgTab","LtgClippingTab","LtgGuiUtility"],"src_usedBy":["ClippingHighlightStyle","LtgClippingTab"],"src_extensionPoints":[],"foldedInto":"ltg-clipping-tab"},{"id":"clipping-highlight-style","name":"ClippingHighlightStyle","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgClippingTab.cs","src_lines":[13,17],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":["BuriedPortionOnly","WholeObject"],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["ClippingCandidate","ClippingCandidateFinder","ClippingDisplayMode","ClippingHighlightRenderer","ILtgTab","LtgClippingTab","LtgGuiUtility"],"src_usedBy":["ClippingDisplayMode","LtgClippingTab"],"src_extensionPoints":[],"foldedInto":"ltg-clipping-tab"}]},{"id":"clipping-candidate-finder","name":"ClippingCandidateFinder","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/ClippingCandidateFinder.cs","src_lines":[23,97],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"The detection half of the Level Transform Guidance, and deliberately the DUMB half: a cheap, over-inclusive proximity test rather than exact penetration math. Its only job is deciding which objects get the highlight — the shader then shows the actual truth and a person judges intent, which is the one thing no amount of geometry math can determine.  That trade is what makes this work on mixed greybox + final-art levels at all: Physics.ComputePenetration (the exact option) doesn't support non-convex MeshColliders, which is exactly what stairs/architecture usually are. An over-inclusive bounds test works against ANY collider type, and a false positive costs nothing — the object gets highlighted, shows no red, and you move on.","src_serialized":[],"src_members":[{"id":"PassesSubjectFilter(GameObject, LayerMask, bool)","sig":"public static bool PassesSubjectFilter(GameObject go, LayerMask subjectMask, bool ignoreSubjectMask)","kind":"method","name":"PassesSubjectFilter","static":true,"comment":null},{"id":"TryFindOverlap(GameObject, Bounds, LayerMask, float, out GameObject, out int)","sig":"public static bool TryFindOverlap(GameObject subject, Bounds worldBounds, LayerMask targetMask, float overlapTolerance, out GameObject firstTarget, out int targetCount)","kind":"method","name":"TryFindOverlap","static":true,"comment":"overlapTolerance SHRINKS the tested bounds before querying, which is what keeps normal resting contact out of the results: a crate sitting correctly on a floor touches it exactly, so a shrunk box no longer reaches it, while a crate genuinely sunk deeper than the tolerance still overlaps. That one knob is the difference between a useful list and a list containing every prop in the level."},{"id":"GetWorldBounds(GameObject, bool)","sig":"public static Bounds? GetWorldBounds(GameObject go, bool useColliderBounds)","kind":"method","name":"GetWorldBounds","static":true,"comment":"Collider bounds for Collider mode (traversal/metrics — what actually blocks the player), renderer bounds for Mesh mode (visual quality — what you actually see). These genuinely differ, which is the whole reason the tool has two modes."},{"id":"FindCandidates(IEnumerable<GameObject>, LayerMask, LayerMask, bool, float, bool)","sig":"public static List<ClippingCandidate> FindCandidates(IEnumerable<GameObject> subjects, LayerMask subjectMask, LayerMask targetMask, bool ignoreSubjectMask, float overlapTolerance, bool useColliderBounds)","kind":"method","name":"FindCandidates","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"The detection half of the Level Transform Guidance, and deliberately the DUMB half: a cheap, over-inclusive proximity...","src_uses":["ClippingCandidate","GroundSnapper"],"src_usedBy":["ClippingCandidate","ClippingDisplayMode","ClippingHighlightStyle","LtgClippingTab"],"src_extensionPoints":[],"parts":[{"id":"clipping-candidate","name":"ClippingCandidate","cat":"EditorTools","src_typeKind":"struct","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/ClippingCandidateFinder.cs","src_lines":[7,12],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"One flagged object plus what it appears to be clipping into.","src_serialized":[],"src_members":[{"id":"subject","sig":"public GameObject subject","kind":"field","name":"subject","static":false,"comment":null},{"id":"firstTarget","sig":"public GameObject firstTarget","kind":"field","name":"firstTarget","static":false,"comment":null},{"id":"targetCount","sig":"public int targetCount","kind":"field","name":"targetCount","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"One flagged object plus what it appears to be clipping into.","src_uses":["ClippingCandidateFinder","GroundSnapper"],"src_usedBy":["ClippingCandidateFinder","ClippingDisplayMode","ClippingHighlightStyle","LtgClippingTab"],"src_extensionPoints":[],"foldedInto":"clipping-candidate-finder"}]},{"id":"clipping-highlight-renderer","name":"ClippingHighlightRenderer","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/ClippingHighlightRenderer.cs","src_lines":[12,119],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"The drawing half of the Level Transform Guidance — draws a flagged object a second time with the ZTest Greater highlight material, so only its buried portion shows.  Deliberately does NOT swap materials on the objects themselves: a material swap that errors mid-scan leaves debug materials baked into a real scene, and undoing that by hand is miserable. Drawing an extra pass via Graphics.DrawMeshNow touches nothing the scene actually owns, so toggling the tool off is always clean.","src_serialized":[],"src_members":[{"id":"DrawMeshHighlight(GameObject, Material, int)","sig":"public static void DrawMeshHighlight(GameObject subject, Material material, int materialPass)","kind":"method","name":"DrawMeshHighlight","static":true,"comment":"Mesh mode: the visual model, for judging visual-quality clipping (seams, sunk props). materialPass selects the shader's highlight style — 0 = buried portion only, 1 = whole object."},{"id":"DrawColliderHighlight(GameObject, Material, int)","sig":"public static void DrawColliderHighlight(GameObject subject, Material material, int materialPass)","kind":"method","name":"DrawColliderHighlight","static":true,"comment":"Collider mode: the actual collision shapes, for judging traversal/metric problems — these often differ from the visual mesh, which is exactly the class of bug you'd otherwise never see."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"The drawing half of the Level Transform Guidance — draws a flagged object a second time with the ZTest Greater...","src_uses":[],"src_usedBy":["ClippingDisplayMode","ClippingHighlightStyle","LtgClippingTab"],"src_extensionPoints":[]}]},{"title":"Measuring tape","entries":[{"id":"ltg-measuring-tape-tab","name":"LtgMeasuringTapeTab","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgMeasuringTapeTab.cs","src_lines":[37,294],"src_base":null,"src_implements":["ILtgTab"],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"Title","sig":"public string Title => \"Measuring Tape\"","kind":"property","name":"Title","static":false,"comment":null},{"id":"IconName","sig":"public string IconName => \"d_Grid.MoveTool\"","kind":"property","name":"IconName","static":false,"comment":null},{"id":"Activate()","sig":"public void Activate() => SceneView.duringSceneGui += OnSceneGUI","kind":"method","name":"Activate","static":false,"comment":"Only subscribed while this tab is the active one — otherwise it would eat Scene-view clicks while the designer is working in a different tab entirely."},{"id":"Deactivate()","sig":"public void Deactivate()","kind":"method","name":"Deactivate","static":false,"comment":null},{"id":"TotalLength()","sig":"public float TotalLength()","kind":"method","name":"TotalLength","static":false,"comment":"Public so the total-path math is directly testable without any Scene-view interaction."},{"id":"AddPointForTest(Vector3)","sig":"public void AddPointForTest(Vector3 point) => points.Add(point)","kind":"method","name":"AddPointForTest","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Measuring Tape tab: click points in the Scene view to measure distances, labelled per segment.","overview":["The Measuring Tape's tab UI. Captures Scene-view clicks, stores the points and draws the labels; converts units through MeasurementUnits. Settings and gotchas are documented on LevelTransformGuidance."],"src_uses":["FixedPlaneAxis","ILtgTab","MeasurementMode","MeasurementUnit","MeasurementUnits","TapeLabelStyle"],"src_usedBy":["FixedPlaneAxis","LevelTransformGuidanceWindow","MeasurementMode","TapeLabelStyle"],"src_extensionPoints":[],"parts":[{"id":"fixed-plane-axis","name":"FixedPlaneAxis","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgMeasuringTapeTab.cs","src_lines":[12,12],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["ILtgTab","LtgMeasuringTapeTab","MeasurementMode","MeasurementUnit","MeasurementUnits","TapeLabelStyle"],"src_usedBy":["LtgMeasuringTapeTab","MeasurementMode","TapeLabelStyle"],"src_extensionPoints":[],"foldedInto":"ltg-measuring-tape-tab"},{"id":"measurement-mode","name":"MeasurementMode","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgMeasuringTapeTab.cs","src_lines":[11,11],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"3D = always raycast real scene colliders — a click that misses geometry is REJECTED rather than guessed at, so every recorded point is a true, camera-independent world position. 2D = always project onto a FIXED world plane (never the camera's current view), so points stay consistent no matter how you orbit/pan the Scene view between clicks.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"3D = always raycast real scene colliders — a click that misses geometry is REJECTED rather than guessed at, so every...","src_uses":["FixedPlaneAxis","ILtgTab","LtgMeasuringTapeTab","MeasurementUnit","MeasurementUnits","TapeLabelStyle"],"src_usedBy":["FixedPlaneAxis","LtgMeasuringTapeTab","TapeLabelStyle"],"src_extensionPoints":[],"foldedInto":"ltg-measuring-tape-tab"},{"id":"tape-label-style","name":"TapeLabelStyle","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgMeasuringTapeTab.cs","src_lines":[23,35],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Measuring Tape tab: click points in the Scene view to measure distances between them — each segment labelled at its midpoint, any number of points (A-B-C-D...). Middle-click clears (left as the normal camera-orbit button; right-click stays free for Unity's own Scene view context menu / fly-look).  Re-housed from its former standalone window into this hub, behaviour unchanged: level design is a mode of working, and measuring a gap, checking a prop isn't sunk into the stairs, and stepping back to see whether a wing is under-dressed all happen in the same sitting. It also now shares its unit conversion with the Heatmap tab, so a cell size and a measured distance are expressed in the same terms. How the distance labels stay legible against arbitrary level geometry.","src_serialized":[],"src_members":[],"src_enumValues":["Badge","AutoContrast","FixedColor"],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Measuring Tape tab: click points in the Scene view to measure distances between them — each segment labelled at its...","src_uses":["FixedPlaneAxis","ILtgTab","LtgMeasuringTapeTab","MeasurementMode","MeasurementUnit","MeasurementUnits"],"src_usedBy":["FixedPlaneAxis","LtgMeasuringTapeTab","MeasurementMode"],"src_extensionPoints":[],"foldedInto":"ltg-measuring-tape-tab"}]},{"id":"measurement-units","name":"MeasurementUnits","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/MeasurementUnits.cs","src_lines":[12,48],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Shared unit conversion for the Level Transform Guidance hub — used by the Measuring Tape tab (to label distances) AND the Heatmap tab (to let you express cell size in a unit you actually think in, so the grid doubles as a measurable guideline). Exactly the kind of small shared plumbing the hub exists to make possible rather than each tool re-deriving it.  Unity world units are conventionally treated as METERS throughout the engine (physics especially), so \"meters\" is the base both directions convert through.","src_serialized":[],"src_members":[{"id":"FromMeters(float, MeasurementUnit)","sig":"public static float FromMeters(float meters, MeasurementUnit unit)","kind":"method","name":"FromMeters","static":true,"comment":null},{"id":"ToMeters(float, MeasurementUnit)","sig":"public static float ToMeters(float value, MeasurementUnit unit)","kind":"method","name":"ToMeters","static":true,"comment":null},{"id":"Suffix(MeasurementUnit)","sig":"public static string Suffix(MeasurementUnit unit)","kind":"method","name":"Suffix","static":true,"comment":null},{"id":"Format(float, MeasurementUnit)","sig":"public static string Format(float meters, MeasurementUnit unit) => $\"{FromMeters(meters, unit):F2} {Suffix(unit)}\"","kind":"method","name":"Format","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Shared unit conversion for the Level Transform Guidance hub — used by the Measuring Tape tab (to label distances) AND...","src_uses":["MeasurementUnit"],"src_usedBy":["FixedPlaneAxis","LtgHeatmapTab","LtgMeasuringTapeTab","MeasurementMode","MeasurementUnit","TapeLabelStyle"],"src_extensionPoints":[],"parts":[{"id":"measurement-unit","name":"MeasurementUnit","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/MeasurementUnits.cs","src_lines":[3,3],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["MeasurementUnits"],"src_usedBy":["FixedPlaneAxis","LtgHeatmapTab","LtgMeasuringTapeTab","MeasurementMode","MeasurementUnits","TapeLabelStyle"],"src_extensionPoints":[],"foldedInto":"measurement-units"}]}]},{"title":"Snap to mouse","entries":[{"id":"ltg-snap-to-mouse-tab","name":"LtgSnapToMouseTab","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/LevelTransformGuidance/Editor/LtgSnapToMouseTab.cs","src_lines":[13,92],"src_base":null,"src_implements":["ILtgTab"],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Snap To Mouse tab: with a GameObject selected, hover the Scene view and press a key — the selected object teleports to whatever real geometry the mouse currently points at. A one-shot action (not a held-key drag, not click-to-place) — press the key, the object jumps once, done.  3D-only, always raycasts real scene colliders — same reasoning as the Measuring Tape's 3D mode: a fixed-plane fallback would let the snap land somewhere with no real surface under it, defeating the point of a PLACEMENT tool (a measuring point can be abstract; a snapped-to prop shouldn't float).","src_serialized":[],"src_members":[{"id":"Title","sig":"public string Title => \"Snap To Mouse\"","kind":"property","name":"Title","static":false,"comment":null},{"id":"IconName","sig":"public string IconName => \"d_MoveTool\"","kind":"property","name":"IconName","static":false,"comment":null},{"id":"Activate()","sig":"public void Activate() => SceneView.duringSceneGui += OnSceneGUI","kind":"method","name":"Activate","static":false,"comment":null},{"id":"Deactivate()","sig":"public void Deactivate() => SceneView.duringSceneGui -= OnSceneGUI","kind":"method","name":"Deactivate","static":false,"comment":null},{"id":"TrySnapSelectedObjectToMouse(Vector2)","sig":"public bool TrySnapSelectedObjectToMouse(Vector2 mouseScreenPosition)","kind":"method","name":"TrySnapSelectedObjectToMouse","static":false,"comment":"Public so a self-test — or a hotkey/menu item bound differently later — can trigger a snap without a real Scene-view Event. Returns false (does nothing) if there's no selection or no collider under the given screen point, exactly like Measuring Tape's 3D mode rejects a miss rather than guessing."},{"id":"SnapTransform(Transform, Vector3, Vector3, bool)","sig":"public static void SnapTransform(Transform target, Vector3 worldPoint, Vector3 surfaceNormal, bool alignRotation)","kind":"method","name":"SnapTransform","static":true,"comment":"The actual transform math, pulled out as a static function so a self-test can drive it directly with synthetic points/normals — same reasoning as every other \"extract the pure logic\" split in this toolkit (LocomotionStateMachine.ClassifyState, DecalMeshBuilder.Build, ...): HandleUtility and a live Scene-view camera aren't available/meaningful in a headless batch-mode test."}],"src_enumValues":[],"src_selfTest":"EditorTools/LevelTransformGuidance/Editor/LtgSnapToMouseTabSelfTest.cs","src_demoScene":[],"entryKind":"editor","status":"published","summary":"Snap To Mouse tab: press a key to teleport the selected object onto the surface under the mouse.","overview":["The Snap To Mouse tab UI and the whole feature — it is small enough to need no helper. Raycasts the Scene view on the key press and moves the selection. Settings and gotchas are documented on LevelTransformGuidance."],"src_uses":["DecalMeshBuilder","ILtgTab","LocomotionStateMachine","LtgGuiUtility"],"src_usedBy":["LevelTransformGuidanceWindow"],"src_extensionPoints":[]}]}],"overview":["Level-design tool for dressing and checking a level, featuring a Clipping Inspector, a Heatmap Grid, a Measuring Tape and Snap To Mouse. Four tabs in one window, sharing units, layer filtering and Scene-view drawing. It reports, it never fixes or grades — every tab surfaces information and leaves the call to you."],"features":[{"name":"Clipping Inspector","what":"scans the level for objects sunk into each other on chosen layers, and paints the buried part."},{"name":"Heatmap Grid","what":"colours a movable grid by how much stuff is in each cell, to find over-dressed and barren areas. Doubles as a ruler."},{"name":"Measuring Tape","what":"click points in the Scene view to measure real distances, labelled per segment."},{"name":"Snap To Mouse","what":"press a key to teleport the selected object onto whatever surface the mouse points at."}],"useCases":["Checking nothing is sunk into the floor before art replaces greybox.","Finding the wing of a level that is under-dressed, or the cluster that is overloaded.","Confirming a doorway, corridor or jump gap is the width the design calls for.","Scattering props onto uneven terrain without hand-editing Y values.","Inspecting one storey of a stacked level in isolation."],"whereToFind":"Toolkit ▸ Level Transform Guidance","walkthrough":[{"group":"Clipping","name":"Subjects (get painted)","what":"Layers that get scanned and highlighted. Only these are painted."},{"group":"Clipping","name":"Targets (clipped into)","what":"Layers a subject may be buried in. Keeping floors here and out of Subjects is why architecture never lights up."},{"group":"Clipping","name":"Mode","what":"Collider checks what blocks the player; Mesh checks what you see. They disagree often."},{"group":"Clipping","name":"Overlap Tolerance","what":"How far things must interpenetrate to count. Raise it to stop normal resting contact being flagged."},{"group":"Clipping","name":"Highlight Style","what":"Buried Portion Only paints just the part inside other geometry, so you see how deep. Whole Object tints all of it."},{"group":"Clipping","name":"Highlight Selection Live","what":"Highlights as you select, without running a scan."},{"group":"Clipping","name":"Scan Whole Level / Scan Selection","what":"Runs the check. Results list has a Select button per row."},{"group":"Heatmap","name":"Region (Center / Size)","what":"The box the grid covers, draggable in the Scene view. X and Z are the footprint; Y is a height slice, counting only objects whose centre is inside it."},{"group":"Heatmap","name":"Cell Size + Unit","what":"Grid square size in your chosen unit. Round numbers make the grid readable as a ruler."},{"group":"Heatmap","name":"Metric","what":"Bounds Volume for visual heaviness; Object Count for a plain tally."},{"group":"Heatmap","name":"Full Red At","what":"The density that counts as fully red. A fixed scale you set, not auto-fitted to the busiest cell."},{"group":"Heatmap","name":"Counted Layers","what":"Which layers contribute to a cell's value."},{"group":"Heatmap","name":"Drape Onto Floor + Floor Layers","what":"Raycasts each cell down so the grid follows terrain instead of one flat plane."},{"group":"Heatmap","name":"Fill Opacity / Draw Through Geometry","what":"Readability only — how strong the colour is, and whether it draws over occluding geometry."},{"group":"Heatmap","name":"Build / Refresh Grid","what":"Rebuilds the grid. It is cached, so do this after moving things."},{"group":"Measuring Tape","name":"Measuring Enabled","what":"Turns Scene-view click capture on and off."},{"group":"Measuring Tape","name":"Mode","what":"3D raycasts real colliders and rejects clicks that hit nothing. 2D projects onto a fixed world plane, for measuring across open space."},{"group":"Measuring Tape","name":"Fixed Plane","what":"Which world plane 2D mode projects onto (Z, Y or X). Never the camera's view, so points hold as you orbit."},{"group":"Measuring Tape","name":"Unit","what":"Display unit for distances. Shared with the Heatmap tab."},{"group":"Measuring Tape","name":"Label Style","what":"Badge is legible on any background. Auto Contrast samples the surface colour and can guess wrong on textured art. Fixed Color is a colour you pick."},{"group":"Measuring Tape","name":"Clear Points","what":"Removes all points. Middle-click in the Scene view does the same."},{"group":"Snap To Mouse","name":"Surface Mask","what":"Layers the object is allowed to land on."},{"group":"Snap To Mouse","name":"Snap Key","what":"Key to press while hovering the Scene view. Defaults to V. One press, one jump."},{"group":"Snap To Mouse","name":"Align rotation to surface normal","what":"Also rotates the object's up axis to match the surface, for props that should sit flush on a slope."}],"gotchas":[{"group":"General","title":"It reports, it does not grade","body":"Nothing can tell whether an intersection was intended. An empty result list means 'nothing obvious at these settings', not 'the level is correct'."},{"group":"General","title":"Only the active tab runs","body":"Switching tabs deactivates the old one; closing the window deactivates all four. A tab's Scene-view drawing disappears when you switch away — the data is still there, it just is not being drawn."},{"group":"Clipping","title":"Collider and Mesh modes will disagree","body":"A box collider can read as clean while the visual mesh clearly pokes through a wall, and the reverse. Pick the mode that matches the question."},{"group":"Heatmap","title":"The grid is cached, not live","body":"It rebuilds on demand and when the hierarchy changes, never per frame. Moving objects does not recolour it — press Build / Refresh Grid."},{"group":"Heatmap","title":"Full Red At changes the story","body":"Set it once for a level's scale and leave it, or two readings are not comparable. Too high and dense areas read as mild; too low and everything saturates."},{"group":"Heatmap","title":"The height slice filters by centre","body":"A tall object whose centre sits above the slice is not counted, even though it passes through the area."},{"group":"Measuring Tape","title":"3D mode rejects clicks that miss geometry","body":"That is what guarantees every point is a real world position. Use 2D mode to measure across open space."},{"group":"Snap To Mouse","title":"It snaps the pivot, not the base","body":"A prop whose pivot is at its centre ends up half-buried. Prefabs for this want their pivot at the foot of the model."}],"seeAlso":["GreyboxPlacerWindow","BulkHierarchyToolsWindow","MeasurementUnits"]},{"id":"bulk-hierarchy-tools-window","name":"BulkHierarchyToolsWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/BulkHierarchyTools/Editor/BulkHierarchyToolsWindow.cs","src_lines":[19,152],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Bulk Hierarchy Tools"]},"src_typeComment":"Toolkit/Bulk Hierarchy Tools: two batch operations for a multi-object Hierarchy selection, applied to EACH selected object INDIVIDUALLY rather than to the selection as a group (Unity's own \"Group Selected\", Ctrl+Alt+G, bundles everything under one shared new parent — deliberately not what this does).  - Add Child To Each: creates one new object as a child of every selected object, one per selection — e.g. select 5 panels, add an Image under each of them in one click. Reuses Unity's REAL GameObject creation menu commands (EditorApplication.ExecuteMenuItem) instead of hand-building each object type, so a UI element still gets Unity's own correct defaults (RectTransform sizing, auto-Canvas-creation if a target isn't already under one, etc.) exactly as if you'd used the menu yourself. - Wrap Each In Empty Parent: creates a new empty GameObject as the parent of each selected object, individually, at that object's own world position/rotation — for grouping/offsetting objects one at a time (e.g. wrapping several independent enemies each in their own \"AI root\" for a patrol offset) without lumping them all under one shared node the way Group Selected would.","src_serialized":[{"name":"selectedOptionIndex","type":"int","default":null,"tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"customMenuPath","type":"string","default":"\"GameObject/Create Empty\"","tooltip":null,"header":null,"range":null,"order":1,"comment":null}],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<BulkHierarchyToolsWindow>(\"Bulk Hierarchy Tools\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"AddChildToEach(GameObject[], string)","sig":"public void AddChildToEach(GameObject[] targets, string menuPath)","kind":"method","name":"AddChildToEach","static":false,"comment":"Reuses Unity's OWN creation menu handlers rather than reimplementing per-object-type defaults — deliberately simple (no reflection, no special-casing per menu item) at the cost of only supporting whatever GameObject-creation menu items already exist, which covers every common case.  ExecuteMenuItem's usual \"parent the new object under the current selection\" behavior turns out to depend on there being a real, focused interactive Hierarchy/Scene View — confirmed by a real batch- mode test run: it still creates the object (Selection.activeGameObject afterward IS the new object, same as clicking the menu by hand), but always at the scene root regardless of what was selected. So this explicitly reparents whatever the command just created under the intended target itself, rather than trusting ExecuteMenuItem to have done that part."},{"id":"WrapEachInEmptyParent(GameObject[])","sig":"public void WrapEachInEmptyParent(GameObject[] targets)","kind":"method","name":"WrapEachInEmptyParent","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Toolkit/Bulk Hierarchy Tools: two batch operations for a multi-object Hierarchy selection, applied to EACH selected...","src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"greybox-placer-window","name":"GreyboxPlacerWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/GreyboxPlacer/Editor/GreyboxPlacerWindow.cs","src_lines":[12,95],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Greybox Placer"]},"src_typeComment":"Window > Toolkit > Greybox Placer: click in the Scene view (in Edit mode, not Play mode) to stamp grid-snapped blocks for fast 3D level blockouts. This is deliberately NOT a ProBuilder replacement — it stamps whole prefabs/primitives, it doesn't edit meshes (no vertices/faces/extrude/boolean). Use this for the rough \"shape of the level\" pass, then ProBuilder (or real art) for anything beyond simple stamped blocks. Requires a collider somewhere in the scene (e.g. a ground plane) for the placement raycast to hit.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<GreyboxPlacerWindow>(\"Greybox Placer\")","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Window > Toolkit > Greybox Placer: click in the Scene view (in Edit mode, not Play mode) to stamp grid-snapped blocks...","src_uses":["GreyboxBlockMarker","Grid<T>"],"src_usedBy":["GreyboxBlockMarker"],"src_extensionPoints":[]},{"id":"greybox-block-marker","name":"GreyboxBlockMarker","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/GreyboxPlacer/GreyboxBlockMarker.cs","src_lines":[11,11],"src_base":"MonoBehaviour","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"","src_uses":["GreyboxPlacerWindow"],"src_usedBy":["GreyboxPlacerWindow"],"src_extensionPoints":[]},{"id":"locomotion-animator-generator-window","name":"LocomotionAnimatorGeneratorWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/AnimatorGenerator/Editor/LocomotionAnimatorGeneratorWindow.cs","src_lines":[16,243],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Locomotion Animator Generator"]},"src_typeComment":"Window > Toolkit > Locomotion Animator Generator: select a folder of AnimationClips (or an object with clips as sub-assets, e.g. an imported FBX) and this builds a basic Idle/Walk/Run blend tree + Jump + Hang/Climb Animator Controller automatically — matching clips by name (case-insensitive substring: \"idle\", \"walk\", \"run\", \"jump\", \"hang\"/\"ledge\", \"climb\") instead of manually dragging clips into the Animator window every time. The Speed float this generates lines up 1:1 with Toolkit.Controller.LocomotionStateMachine.NormalizedSpeed (0=idle, 1=walk, 2=run) — see Toolkit/Controller/Locomotion/LocomotionAnimatorDriver.cs for the runtime bridge that feeds it.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<LocomotionAnimatorGeneratorWindow>(\"Locomotion Animator Generator\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"GenerateFromFolder(string, string)","sig":"public static AnimatorController GenerateFromFolder(string folderPath, string outputPath)","kind":"method","name":"GenerateFromFolder","static":true,"comment":null},{"id":"GenerateFromClips(AnimationClip, AnimationClip, AnimationClip, AnimationClip, string)","sig":"public static AnimatorController GenerateFromClips(AnimationClip idle, AnimationClip walk, AnimationClip run, AnimationClip jump, string outputPath)","kind":"method","name":"GenerateFromClips","static":true,"comment":"Separated from GenerateFromFolder so it's directly testable/callable with explicit clips, without needing real assets on disk in a folder. hang/climb default to null via overload below so existing callers built before Ledge Climb support don't need to change."},{"id":"GenerateFromClips(AnimationClip, AnimationClip, AnimationClip, AnimationClip, AnimationClip, AnimationClip, string)","sig":"public static AnimatorController GenerateFromClips(AnimationClip idle, AnimationClip walk, AnimationClip run, AnimationClip jump, AnimationClip hang, AnimationClip climb, string outputPath)","kind":"method","name":"GenerateFromClips","static":true,"comment":null},{"id":"RunSelfTest()","sig":"public static void RunSelfTest()","kind":"method","name":"RunSelfTest","static":true,"comment":"Not exposed as a [MenuItem] on purpose — a leaf item and a submenu can't coexist at the same menu path in Unity, and this only needs to be reachable via -executeMethod for verification anyway. Creates real synthetic clip assets and runs the actual generator against them, then checks the resulting controller has the expected parameters/states — stronger than a compile-only check."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Window > Toolkit > Locomotion Animator Generator: select a folder of AnimationClips (or an object with clips as...","src_uses":["LedgeClimbController","LocomotionAnimatorDriver","LocomotionStateMachine"],"src_usedBy":["LocomotionAnimatorDriver","LocomotionState","LocomotionStateMachine"],"src_extensionPoints":[]},{"id":"batch-asset-renamer-window","name":"BatchAssetRenamerWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/BatchAssetRenamer/Editor/BatchAssetRenamerWindow.cs","src_lines":[23,159],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Batch Asset Renamer"]},"src_typeComment":"Toolkit/Batch Asset Renamer: select assets in the Project window OR GameObjects in the Hierarchy, type a new base name, and rename all of them in one pass. Tick \"Add Numbering\" to get \"Name - 1\", \"Name - 2\", ... instead of every item getting the identical name (Project-window assets would otherwise get auto-disambiguated by Unity's own \" 1\"/\" 2\" suffixing via AssetDatabase.RenameAsset — fine as a fallback, but numbering is the actually-intended feature here; Hierarchy GameObjects don't even get that fallback, since sibling GameObjects are allowed to share an identical name).  Ordering: numbers are assigned by the CURRENT names sorted alphabetically, not by whatever arbitrary order multi-selection happens to report (Unity's Selection order depends on click order, which isn't something a person can predict/reproduce) — so the same selection always numbers the same way no matter how it was selected.  Which window the selection came from changes what renaming actually costs: AssetDatabase.RenameAsset does NOT participate in Unity's Undo stack (asset operations generally don't), so a Project-window rename gets a confirmation dialog warning it can't be undone through Ctrl+Z. A Hierarchy GameObject's name IS a normal serialized property, so Undo.RecordObject covers it fully — Ctrl+Z genuinely reverts it.","src_serialized":[{"name":"newName","type":"string","default":"\"\"","tooltip":null,"header":null,"range":null,"order":0,"comment":null},{"name":"useNumbering","type":"bool","default":null,"tooltip":null,"header":null,"range":null,"order":1,"comment":null},{"name":"startingNumber","type":"int","default":"1","tooltip":null,"header":null,"range":null,"order":2,"comment":null}],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<BatchAssetRenamerWindow>(\"Batch Asset Renamer\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"BuildNewNames(int)","sig":"public string[] BuildNewNames(int count)","kind":"method","name":"BuildNewNames","static":false,"comment":"Public (not just wired to the button) so the actual naming logic is directly unit-testable."},{"id":"SetPreviewState(string, bool, int)","sig":"public void SetPreviewState(string name, bool numbering, int startNumber)","kind":"method","name":"SetPreviewState","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Renames every selected asset or GameObject in one pass, with optional deterministic numbering and a preview.","problem":"Renaming forty sprites to Tile_1 … Tile_40 by hand is twenty minutes of F2 and typos, and Unity offers nothing for it. The awkward part is not the loop, it is that the same selection has to behave sensibly from two completely different windows: Project-window assets live on disk and rename through AssetDatabase, Hierarchy GameObjects are ordinary serialized objects. Those two paths differ in what undo means, in whether duplicate names are even legal, and in what a failed rename costs you — which is why this is a window with a preview and a confirmation rather than a one-line menu command.","whereToFind":"Toolkit ▸ Batch Asset Renamer. The window docks like any other; it repaints itself whenever the selection changes, so you can leave it open and click around the Project window or Hierarchy and watch the preview follow along. It reads the current selection live — there is nothing to drag into it.","params":[{"field":"newName","why":"The base name every selected item gets. With numbering off, all of them get exactly this.","tuning":"Left blank, the window shows 'Enter a new name to see a preview' and the rename button does not appear at all, so an empty field can never fire a rename."},{"field":"useNumbering","why":"Appends ' - 1', ' - 2', … to the base name instead of giving every item the identical name.","tuning":"Worth leaving on for assets. Without it, Unity's own AssetDatabase disambiguation silently appends ' 1'/' 2' with a different separator, and Hierarchy GameObjects get no disambiguation at all — sibling GameObjects are allowed to share a name, so you end up with forty objects called the same thing."},{"field":"startingNumber","why":"First index used when numbering is on; only shown in the window when useNumbering is ticked.","tuning":"Set it to continue an existing run — rename a second batch starting at 41 and it joins the first cleanly. Nothing stops a negative or zero start."}],"walkthrough":[{"step":"Open Toolkit ▸ Batch Asset Renamer and select nothing.","whatYouSee":"'0 asset(s) selected in the Project window' and a help box telling you to select something. The window is never blank or ambiguous about why it is idle."},{"step":"Select several assets in the Project window.","whatYouSee":"The header count updates immediately, without clicking into the window, because OnEnable subscribes to Selection.selectionChanged and repaints."},{"step":"Select GameObjects in the Hierarchy instead.","whatYouSee":"The wording flips to 'item(s) selected in Hierarchy'. The window decided that from EditorUtility.IsPersistent, not from which window has focus — anything not living on disk means you are working in the scene."},{"step":"Type a base name and tick Add Numbering.","whatYouSee":"A scrolling old → new preview list appears, capped at 300px high. The order is the CURRENT names sorted alphabetically, not the order you clicked, so the same selection always numbers the same way."},{"step":"Press Rename.","whatYouSee":"A confirmation dialog whose wording depends on the source: a Hierarchy rename says it CAN be undone with Ctrl+Z, a Project rename says it does NOT go through the undo stack. Cancel does nothing at all."},{"step":"Press Ctrl+Z after a Hierarchy rename.","whatYouSee":"Every renamed object reverts in a single undo step, not one per object — the loop is wrapped in Undo.SetCurrentGroupName plus Undo.CollapseUndoOperations."}],"useCases":["Normalising an imported art pack whose files arrived as texture_001_final_v2 and similar.","Numbering a set of level pieces, waypoints or spawn markers so they read in order in the Hierarchy.","Renaming a batch of ScriptableObject assets after a naming-convention change, where the alternative is F2 forty times.","Renumbering a second batch onto the end of an existing run by setting Starting Number."],"apiNotes":{"ShowWindow()":"The [MenuItem] entry point. Calling it from your own editor code opens or focuses the same dockable window.","BuildNewNames(int)":"Deliberately public rather than private-and-wired-to-the-button, so the naming logic can be unit-tested without a GUI. Returns the array the preview displays and the rename then applies, so what you see really is what runs.","SetPreviewState(string, bool, int)":"Sets the three window fields from code. Useful for scripting a rename or for driving the window from a test."},"gotchas":[{"title":"A Project-window rename cannot be undone with Ctrl+Z","body":"AssetDatabase.RenameAsset does not participate in Unity's undo stack — asset operations generally do not. The confirmation dialog says so explicitly, and that dialog is the only safety net: once confirmed, getting the old names back means renaming them back by hand or reverting in version control. Hierarchy GameObjects are the opposite case, because a GameObject name is an ordinary serialized property and Undo.RecordObject covers it fully."},{"title":"Numbering follows alphabetical order, not click order","body":"Selection.objects reports items in whatever order Unity happened to register the clicks, which a person cannot predict or reproduce. Both selection paths therefore sort by current name before numbering. That makes the result deterministic, but it also means you cannot impose an arbitrary order by clicking in the order you want — rename to a sortable intermediate name first if you need a specific sequence."},{"title":"Hierarchy selection wins whenever both windows have something highlighted","body":"GetSelectionKind returns Hierarchy as soon as ANY selected GameObject is non-persistent, even if the Project window still shows an earlier highlight. Unity's Selection always reflects the window you interacted with most recently, so this matches what you just clicked — but the header text is the thing to read before pressing Rename, not the coloured highlight in either window."},{"title":"A prefab asset's root counts as Project, not Hierarchy","body":"EditorUtility.IsPersistent is true for a prefab ASSET's own root GameObject, so selecting prefabs in the Project window takes the AssetDatabase path — the no-undo path — even though they are GameObjects. An instance of that prefab sitting in an open scene is non-persistent and takes the Hierarchy path instead."},{"title":"Individual asset renames can fail quietly","body":"RenameProjectSelection skips anything with an empty asset path and ignores the string AssetDatabase.RenameAsset returns, which is an error message when the rename is rejected (an illegal character, a name collision). Nothing is logged, so a batch can come back partially applied with no indication of which items were refused. Check the result in the Project window rather than assuming."}],"seeAlso":["BulkHierarchyToolsWindow","FindReferencesWindow","ScriptableObjectTableWindow"],"src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"find-references-window","name":"FindReferencesWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/FindReferences/Editor/FindReferencesWindow.cs","src_lines":[17,161],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Find References","Assets/Toolkit/Find References In Project"]},"src_typeComment":"Toolkit/Find References: \"what actually uses this?\" before you rename/delete/refactor it. Drag any asset (or a scene object, for the scene search) into the target field, then search either or both: - Search Open Scene(s): walks every GameObject in every currently loaded scene and inspects each component's serialized fields directly (via SerializedObject/SerializedProperty), so it finds real Inspector-wired references, not a fragile text/name match. - Search Project Assets: uses AssetDatabase.GetDependencies(path, recursive: false) on every prefab/ material/ScriptableObject/scene/controller/clip in the project — Unity's own dependency database, not a raw text search through .prefab/.asset YAML, so it's both fast and accurate.","src_serialized":[{"name":"target","type":"Object","default":null,"tooltip":null,"header":null,"range":null,"order":0,"comment":null}],"src_members":[{"id":"SceneReference","sig":"public struct SceneReference","kind":"property","name":"SceneReference","static":false,"comment":null},{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<FindReferencesWindow>(\"Find References\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"SearchScenes()","sig":"public void SearchScenes()","kind":"method","name":"SearchScenes","static":false,"comment":"Public (not just called from OnGUI) so this is directly unit-testable without needing a real window."},{"id":"SearchProject()","sig":"public void SearchProject()","kind":"method","name":"SearchProject","static":false,"comment":null},{"id":"SceneResults","sig":"public IReadOnlyList<SceneReference> SceneResults => sceneResults","kind":"property","name":"SceneResults","static":false,"comment":null},{"id":"ProjectResults","sig":"public IReadOnlyList<Object> ProjectResults => projectResults","kind":"property","name":"ProjectResults","static":false,"comment":null},{"id":"SetTarget(Object)","sig":"public void SetTarget(Object newTarget) => target = newTarget","kind":"method","name":"SetTarget","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Toolkit/Find References: \"what actually uses this?\" before you rename/delete/refactor it.","src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"todo-scanner-window","name":"TodoScannerWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/TodoScanner/Editor/TodoScannerWindow.cs","src_lines":[12,80],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/TODO Scanner"]},"src_typeComment":"Window > Toolkit > TODO Scanner: scans every .cs file under Assets for TODO/FIXME/HACK comments and lists them with a click-to-open jump straight to the line.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<TodoScannerWindow>(\"TODO Scanner\")","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Window > Toolkit > TODO Scanner: scans every .cs file under Assets for TODO/FIXME/HACK comments and lists them with a...","src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"csv-table-window","name":"CsvTableWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/CsvTableEditor/Editor/CsvTableWindow.cs","src_lines":[12,97],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/CSV Table Editor"]},"src_typeComment":"Window > Toolkit > CSV Table Editor: load a CSV, edit values directly in a grid inside Unity, save back — a lightweight in-Editor \"balancing sheet\" for design data without leaving Unity or fighting an Excel/Sheets round-trip for every small tweak.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<CsvTableWindow>(\"CSV Table Editor\")","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Window > Toolkit > CSV Table Editor: load a CSV, edit values directly in a grid inside Unity, save back — a lightweight...","src_uses":["CsvUtility"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"csv-to-scriptable-object-importer","name":"CsvToScriptableObjectImporter","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/CsvToScriptableObject/Editor/CsvToScriptableObjectImporter.cs","src_lines":[15,169],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/CSV to ScriptableObject Importer"]},"src_typeComment":"Window > Toolkit > CSV to ScriptableObject Importer: point at a CSV with a header row matching field names on a GameDataAsset subclass, and this creates/updates one asset per data row — turn a spreadsheet of 50 item stats into 50 balanced data assets in one click instead of hand-editing each one.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<CsvToScriptableObjectImporter>(\"CSV to ScriptableObject Importer\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"static(int, int)","sig":"public static (int created, int updated) Import(Type dataType, string csvPath, string outputFolder, string idColumnName)","kind":"method","name":"static","static":true,"comment":null},{"id":"RunSelfTest()","sig":"public static void RunSelfTest()","kind":"method","name":"RunSelfTest","static":true,"comment":"Not exposed as a [MenuItem] on purpose (same reasoning as the animator generator's self-test) — creates a real synthetic CSV, imports it against the existing DemoItemData type, and checks the resulting assets have the expected field values."}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Window > Toolkit > CSV to ScriptableObject Importer: point at a CSV with a header row matching field names on a...","src_uses":["CsvUtility","GameDataAsset"],"src_usedBy":[],"src_extensionPoints":[]},{"id":"scriptable-object-table-window","name":"ScriptableObjectTableWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/ScriptableObjectTableView/Editor/ScriptableObjectTableWindow.cs","src_lines":[20,129],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/ScriptableObject Table View"]},"src_typeComment":"Toolkit/ScriptableObject Table View: select several ScriptableObject assets of the SAME concrete type in the Project window and see/edit every one of them side by side as spreadsheet rows — including dragging in a different Object/ScriptableObject reference directly in a cell, which just works because every cell is drawn with Unity's own SerializedProperty field drawer (the same one the normal Inspector uses), not a hand-rolled per-type renderer. Deliberately kept SEPARATE from EditorTools/CsvTableEditor — that tool edits plain CSV files, this one edits real asset objects through the normal serialization pipeline (full Undo support, proper asset dirtying, no export/import round-trip).  Known limitation: a field that draws as a multi-line block in the normal Inspector (a List<T>, a nested [Serializable] class) still does that here too — it expands vertically inside its cell rather than collapsing into a compact one-line summary, which looks fine for one or two such fields but gets messy with several. This tool is at its best comparing mostly scalar/reference fields side by side.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow() => GetWindow<ScriptableObjectTableWindow>(\"SO Table View\")","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"Refresh()","sig":"public void Refresh()","kind":"method","name":"Refresh","static":false,"comment":"Public (not just wired to selection-changed) so a self-test can exercise it directly without needing to fake an actual Project-window selection."},{"id":"CollectFieldNames(SerializedObject)","sig":"public static string[] CollectFieldNames(SerializedObject serializedObject)","kind":"method","name":"CollectFieldNames","static":true,"comment":"Walks the FIRST object's visible serialized properties (skipping m_Script, the header field every ScriptableObject carries) to get the column set — the same top-level property walk DrawDefaultInspector uses internally, just collected once into names instead of drawn immediately."}],"src_enumValues":[],"src_selfTest":"EditorTools/ScriptableObjectTableView/Editor/ScriptableObjectTableWindowSelfTest.cs","src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Toolkit/ScriptableObject Table View: select several ScriptableObject assets of the SAME concrete type in the Project...","src_uses":[],"src_usedBy":[],"src_extensionPoints":[]},{"id":"player-prefs-editor-window","name":"PlayerPrefsEditorWindow","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/PlayerPrefsEditor/Editor/PlayerPrefsEditorWindow.cs","src_lines":[44,231],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/PlayerPrefs Editor"]},"src_typeComment":"Toolkit/PlayerPrefs Editor: UnityEngine.PlayerPrefs has NO \"list all keys\" method, which makes a normal editor window impossible to build against it directly. On Windows, PlayerPrefs actually live in the registry under HKCU\\Software\\<Company>\\<Product>, one value per key (named \"<key>_h<hash>\" — Unity appends a project-specific hash suffix to every key).  This tool reads THAT registry key purely to DISCOVER which keys exist (enumerate value names, strip the hash suffix) — it never parses Unity's undocumented on-disk VALUE format itself. Every actual read or write of a value goes through the real UnityEngine.PlayerPrefs API, which is guaranteed correct since it's Unity's own code doing the encoding/decoding, not a reverse-engineered guess at an undocumented binary layout — getting that wrong on a WRITE could silently corrupt real save data, which isn't a risk worth taking when the actual API is sitting right there to use instead.  Editor-only and WINDOWS-SPECIFIC by choice — macOS stores PlayerPrefs in a .plist and Linux in a config file, each needing its own discovery method this tool doesn't attempt.  The one place a real guess is unavoidable: distinguishing an Int/Float/String key from the registry alone, since PlayerPrefs.GetInt/GetFloat/GetString each need the CALLER to already know the type. CONFIRMED BY TESTING (not assumed): PlayerPrefs.SetInt AND PlayerPrefs.SetFloat both write a plain RegistryValueKind.DWord — Unity stores a float's raw 4 bytes reinterpreted as the DWord's bit pattern rather than tagging it Binary, so DWord alone CANNOT tell Int and Float apart; this is a routine ambiguity affecting every float key, not a rare edge case. Classified by value kind (DWord -> Int as a default guess, Binary -> String) with a manual \"type\" dropdown per row that is the ONLY reliable way to correctly view/edit a float key — flip it once and the row re-reads through PlayerPrefs.GetFloat instead, showing the real value.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow()","kind":"method","name":"ShowWindow","static":true,"comment":null},{"id":"Refresh()","sig":"public void Refresh() => entries = DiscoverKeys()","kind":"method","name":"Refresh","static":false,"comment":"Public (not just wired to the Refresh button) so a self-test can drive it directly."},{"id":"DiscoverKeys()","sig":"public static List<PlayerPrefsEntry> DiscoverKeys()","kind":"method","name":"DiscoverKeys","static":true,"comment":"Enumerates every registry VALUE NAME under this project's PlayerPrefs registry key and strips Unity's \"_h<hash>\" suffix to recover the original key name."},{"id":"DiscoverKeys()","sig":"public static List<PlayerPrefsEntry> DiscoverKeys() => new List<PlayerPrefsEntry>()","kind":"method","name":"DiscoverKeys","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":"EditorTools/PlayerPrefsEditor/Editor/PlayerPrefsEditorWindowSelfTest.cs","src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Toolkit/PlayerPrefs Editor: UnityEngine.PlayerPrefs has NO \"list all keys\" method, which makes a normal editor window...","src_uses":["PlayerPrefsEntry","PlayerPrefsValueType"],"src_usedBy":["PlayerPrefsEntry","PlayerPrefsValueType"],"src_extensionPoints":[],"parts":[{"id":"player-prefs-entry","name":"PlayerPrefsEntry","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/PlayerPrefsEditor/Editor/PlayerPrefsEditorWindow.cs","src_lines":[14,18],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"key","sig":"public string key","kind":"field","name":"key","static":false,"comment":null},{"id":"type","sig":"public PlayerPrefsValueType type","kind":"field","name":"type","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["PlayerPrefsEditorWindow","PlayerPrefsValueType"],"src_usedBy":["PlayerPrefsEditorWindow","PlayerPrefsValueType"],"src_extensionPoints":[],"foldedInto":"player-prefs-editor-window"},{"id":"player-prefs-value-type","name":"PlayerPrefsValueType","cat":"EditorTools","src_typeKind":"enum","src_ns":"Toolkit.EditorUtilities","src_file":"EditorTools/PlayerPrefsEditor/Editor/PlayerPrefsEditorWindow.cs","src_lines":[12,12],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["PlayerPrefsEditorWindow","PlayerPrefsEntry"],"src_usedBy":["PlayerPrefsEditorWindow","PlayerPrefsEntry"],"src_extensionPoints":[],"foldedInto":"player-prefs-editor-window"}]},{"id":"button-attribute","name":"ButtonAttribute","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes","src_file":"EditorTools/AttributeDrawers/ButtonAttribute.cs","src_lines":[8,8],"src_base":"Attribute","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Drop above a parameterless method to draw a button in the Inspector that calls it when clicked — handy for \"Regenerate\", \"Test\", \"Reset This\" debug actions without writing a custom Editor script.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"Drop above a parameterless method to draw a button in the Inspector that calls it when clicked — handy for...","src_uses":[],"src_usedBy":["ButtonAttributeEditor"],"src_extensionPoints":[],"parts":[{"id":"button-attribute-editor","name":"ButtonAttributeEditor","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes.Editor","src_file":"EditorTools/AttributeDrawers/Editor/ButtonAttributeEditor.cs","src_lines":[16,33],"src_base":"UnityEditor.Editor","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Applies to every MonoBehaviour's Inspector: draws the normal fields, then adds a button for each parameterless method marked [Button]. No per-script custom Editor needed — this one covers everything automatically. Note: this registers globally for MonoBehaviour, so it's the Inspector shown for any script that doesn't already have its own more specific [CustomEditor] (Unity always prefers the most specific match, so scripts with their own custom Editor are unaffected).","src_serialized":[],"src_members":[{"id":"OnInspectorGUI()","sig":"public override void OnInspectorGUI()","kind":"method","name":"OnInspectorGUI","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Applies to every MonoBehaviour's Inspector: draws the normal fields, then adds a button for each parameterless method...","src_uses":["ButtonAttribute"],"src_usedBy":[],"src_extensionPoints":[],"foldedInto":"button-attribute"}]},{"id":"layer-attribute","name":"LayerAttribute","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes","src_file":"EditorTools/AttributeDrawers/LayerAttribute.cs","src_lines":[6,6],"src_base":"PropertyAttribute","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Drop above an int field to draw it as a Layer dropdown instead of a plain number field.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"Drop above an int field to draw it as a Layer dropdown instead of a plain number field.","src_uses":[],"src_usedBy":["LayerDrawer"],"src_extensionPoints":[],"parts":[{"id":"layer-drawer","name":"LayerDrawer","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes.Editor","src_file":"EditorTools/AttributeDrawers/Editor/LayerDrawer.cs","src_lines":[8,19],"src_base":"PropertyDrawer","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["LayerAttribute"],"src_usedBy":[],"src_extensionPoints":[],"foldedInto":"layer-attribute"}]},{"id":"read-only-attribute","name":"ReadOnlyAttribute","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes","src_file":"EditorTools/AttributeDrawers/ReadOnlyAttribute.cs","src_lines":[9,9],"src_base":"PropertyAttribute","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Drop above any [SerializeField] to show it in the Inspector but prevent editing — useful for a \"live debug view\" field (current state, a computed value) you want visible but not hand-editable. This attribute type must live outside any Editor folder so scripts using it still compile in player builds; the drawer that actually disables the field lives in AttributeDrawers/Editor/ReadOnlyDrawer.cs.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"Drop above any [SerializeField] to show it in the Inspector but prevent editing — useful for a \"live debug view\" field...","src_uses":["ReadOnlyDrawer"],"src_usedBy":["ReadOnlyDrawer"],"src_extensionPoints":[],"parts":[{"id":"read-only-drawer","name":"ReadOnlyDrawer","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes.Editor","src_file":"EditorTools/AttributeDrawers/Editor/ReadOnlyDrawer.cs","src_lines":[8,18],"src_base":"PropertyDrawer","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"GetPropertyHeight(SerializedProperty, GUIContent)","sig":"public override float GetPropertyHeight(SerializedProperty property, GUIContent label)","kind":"method","name":"GetPropertyHeight","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["ReadOnlyAttribute"],"src_usedBy":["ReadOnlyAttribute"],"src_extensionPoints":[],"foldedInto":"read-only-attribute"}]},{"id":"tag-attribute","name":"TagAttribute","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes","src_file":"EditorTools/AttributeDrawers/TagAttribute.cs","src_lines":[6,6],"src_base":"PropertyAttribute","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":true,"src_attributes":{},"src_typeComment":"Drop above a string field to draw it as a Tag dropdown instead of a plain text field.","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"tool","status":"skeleton","summary":"Drop above a string field to draw it as a Tag dropdown instead of a plain text field.","src_uses":[],"src_usedBy":["TagDrawer"],"src_extensionPoints":[],"parts":[{"id":"tag-drawer","name":"TagDrawer","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorAttributes.Editor","src_file":"EditorTools/AttributeDrawers/Editor/TagDrawer.cs","src_lines":[8,19],"src_base":"PropertyDrawer","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["TagAttribute"],"src_usedBy":[],"src_extensionPoints":[],"foldedInto":"tag-attribute"}]},{"id":"task-recaller","name":"TaskRecaller","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorTools.TaskRecaller","src_file":"EditorTools/TaskRecaller/Editor/TaskRecallerWindow.cs","src_lines":[12,163],"src_base":"EditorWindow","src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{"menuItem":["Toolkit/Task Recaller"]},"src_typeComment":"\"Task Recaller\" — shows itself automatically after a real gap away (TaskRecallerService decides when that is), or open it anytime from the menu. Top: a note field for your own future reference — the one thing this tool can't infer on its own. Below: a timeline of what you had selected and which scripts you opened, most recent first, with a one-click jump back to each.","src_serialized":[],"src_members":[{"id":"ShowWindow()","sig":"public static void ShowWindow()","kind":"method","name":"ShowWindow","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"published","summary":"Task Recaller — records what you were working on and offers it back after a break.","src_uses":["SessionEntry","SessionHistory","SessionHistoryStorage","TaskRecallerService"],"src_usedBy":["TaskRecallerService"],"src_extensionPoints":[],"isSystem":true,"systemOf":"TaskRecallerWindow","systemPrimaryId":"task-recaller-window","systemSections":[{"title":"Supporting scripts","entries":[{"id":"task-recaller-service","name":"TaskRecallerService","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorTools.TaskRecaller","src_file":"EditorTools/TaskRecaller/Editor/TaskRecallerService.cs","src_lines":[17,116],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{"initializeOnLoad":true},"src_typeComment":"Runs automatically, no wiring needed — records what you were looking at (Hierarchy/Project selection), which scripts you opened, and detects when you've come back after a real gap so the \"Task Recaller\" window can offer to show itself instead of you having to remember it exists.  What this CANNOT see, on purpose left as an honest gap rather than faked: your actual code editor's open tabs/cursor position (Unity has no API into VS Code/Rider internals — only that you double-clicked a script to open it), and Inspector micro-state like an expanded foldout or an unsaved field edit. The manual note field in the window is the intended answer to that second gap.","src_serialized":[],"src_members":[{"id":"GapMinutes","sig":"public static float GapMinutes","kind":"property","name":"GapMinutes","static":true,"comment":null},{"id":"OnOpenAsset(int, int)","sig":"public static bool OnOpenAsset(int instanceId, int line)","kind":"method","name":"OnOpenAsset","static":true,"comment":"[OnOpenAsset] fires when the user double-clicks an asset to open it — the real, documented hook for \"what did they just open,\" not a guess based on polling. Returning false lets Unity's normal open-in-external-editor behaviour still happen; this only ever observes."},{"id":"RecordNote(string)","sig":"public static void RecordNote(string noteText)","kind":"method","name":"RecordNote","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Runs automatically, no wiring needed — records what you were looking at (Hierarchy/Project selection), which scripts...","src_uses":["SessionEntry","SessionHistory","SessionHistoryStorage","TaskRecallerWindow"],"src_usedBy":["TaskRecallerWindow"],"src_extensionPoints":[]},{"id":"session-history-storage","name":"SessionHistoryStorage","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorTools.TaskRecaller","src_file":"EditorTools/TaskRecaller/Editor/SessionHistoryData.cs","src_lines":[33,73],"src_base":null,"src_implements":[],"src_static":true,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"Persists to UserSettings/ — the folder Unity itself reserves for per-user, per-project editor state that shouldn't go into source control (already covered by Unity's default .gitignore), which is exactly what a \"what was I doing\" breadcrumb trail is.","src_serialized":[],"src_members":[{"id":"Load()","sig":"public static SessionHistory Load()","kind":"method","name":"Load","static":true,"comment":null},{"id":"Save(SessionHistory)","sig":"public static void Save(SessionHistory history)","kind":"method","name":"Save","static":true,"comment":null},{"id":"IsNewSession(DateTime, DateTime, float)","sig":"public static bool IsNewSession(DateTime lastTimestampUtc, DateTime nowUtc, float gapMinutes)","kind":"method","name":"IsNewSession","static":true,"comment":"Pure — no disk/Editor access — so a self-test can assert the \"was I away long enough to count as a new session\" decision directly."},{"id":"IsDuplicateOfLast(SessionEntry, string, string)","sig":"public static bool IsDuplicateOfLast(SessionEntry last, string kind, string globalObjectId)","kind":"method","name":"IsDuplicateOfLast","static":true,"comment":"Pure — avoids logging the same object twice in a row (e.g. clicking the same GameObject repeatedly), without suppressing genuinely different consecutive entries."},{"id":"Append(SessionHistory, SessionEntry)","sig":"public static void Append(SessionHistory history, SessionEntry entry)","kind":"method","name":"Append","static":true,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"Persists to UserSettings/ — the folder Unity itself reserves for per-user, per-project editor state that shouldn't go...","src_uses":["SessionEntry","SessionHistory"],"src_usedBy":["SessionEntry","SessionHistory","TaskRecallerService","TaskRecallerWindow"],"src_extensionPoints":[],"parts":[{"id":"session-entry","name":"SessionEntry","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorTools.TaskRecaller","src_file":"EditorTools/TaskRecaller/Editor/SessionHistoryData.cs","src_lines":[12,22],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"One breadcrumb: a selection change, a script you double-clicked open, or a note you left yourself. Plain serializable data, no MonoBehaviour — JsonUtility handles it directly.","src_serialized":[],"src_members":[{"id":"timestampUtc","sig":"public string timestampUtc; // ISO 8601 — JsonUtility can't serialize DateTime itself","kind":"field","name":"timestampUtc","static":false,"comment":null},{"id":"kind","sig":"public string kind; // \"Selection\" | \"OpenedScript\" | \"Note\"","kind":"field","name":"kind","static":false,"comment":null},{"id":"label","sig":"public string label; // object name, script name, or the note text","kind":"field","name":"label","static":false,"comment":null},{"id":"globalObjectId","sig":"public string globalObjectId; // empty for Note entries — see GlobalObjectId below","kind":"field","name":"globalObjectId","static":false,"comment":null},{"id":"scenePath","sig":"public string scenePath; // which scene a scene GameObject belonged to; empty for project assets/notes","kind":"field","name":"scenePath","static":false,"comment":null},{"id":"startsNewSession","sig":"public bool startsNewSession; // true if a real gap was detected since the previous entry","kind":"field","name":"startsNewSession","static":false,"comment":null},{"id":"TimestampUtc","sig":"public DateTime TimestampUtc => DateTime.Parse(timestampUtc, null, System.Globalization.DateTimeStyles.RoundtripKind)","kind":"property","name":"TimestampUtc","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"One breadcrumb: a selection change, a script you double-clicked open, or a note you left yourself.","src_uses":["SessionHistory","SessionHistoryStorage"],"src_usedBy":["SessionHistory","SessionHistoryStorage","TaskRecallerService","TaskRecallerWindow"],"src_extensionPoints":[],"foldedInto":"session-history-storage"},{"id":"session-history","name":"SessionHistory","cat":"EditorTools","src_typeKind":"class","src_ns":"Toolkit.EditorTools.TaskRecaller","src_file":"EditorTools/TaskRecaller/Editor/SessionHistoryData.cs","src_lines":[25,28],"src_base":null,"src_implements":[],"src_static":false,"src_internal":false,"src_runtime":false,"src_attributes":{},"src_typeComment":"","src_serialized":[],"src_members":[{"id":"List<SessionEntry>()","sig":"public List<SessionEntry> entries = new List<SessionEntry>()","kind":"method","name":"List","static":false,"comment":null}],"src_enumValues":[],"src_selfTest":null,"src_demoScene":[],"entryKind":"editor","status":"skeleton","summary":"","src_uses":["SessionEntry","SessionHistoryStorage"],"src_usedBy":["SessionEntry","SessionHistoryStorage","TaskRecallerService","TaskRecallerWindow"],"src_extensionPoints":[],"foldedInto":"session-history-storage"}]}]}],"overview":["Picks up the thread after you have been away. It records what you had selected and which scripts you opened as you work, and when you come back after a real gap it opens itself with that timeline and a one-click jump back to each item. Runs on its own with nothing to wire up."],"features":[{"name":"Note field","what":"a message to your future self, for the intent no tool can infer."},{"name":"Timeline","what":"selections, opened scripts and notes, newest first, each with a button that jumps you back to it."},{"name":"Auto-open","what":"shows itself on the first launch after a gap longer than your away-time setting."}],"useCases":["Coming back on Monday to a task you were mid-way through on Friday.","Leaving yourself a note about what you were about to try, before closing Unity.","Jumping straight back to the prefab or script you were last working in, without hunting for it."],"whereToFind":"Toolkit ▸ Task Recaller — or it opens itself after a gap","walkthrough":[{"name":"Leave a note for next time","what":"Free text saved as a timeline entry. Save Note is disabled until you type something."},{"name":"Away-time gap (minutes)","what":"How long since your last recorded action before this counts as a new session and the window auto-opens. Defaults to 20."},{"name":"Clear History","what":"Deletes the recorded selections and opened scripts. Notes are entries too, so they go as well — it asks first."},{"name":"Select / Open Scene","what":"On a timeline row: jumps to the object. If it lived in a different scene, it offers to open that scene first."}],"gotchas":[{"title":"It cannot see inside your code editor","body":"Unity has no API into VS Code or Rider, so it records only that you double-clicked a script open — not your tabs, cursor position or unsaved edits. The note field is the intended answer to that gap, and it is deliberately not faked."},{"title":"The gap is measured per Editor process, not per recompile","body":"It uses SessionState, which survives a script recompile but resets on a real relaunch. That is what stops the window popping up after every recompile — but it also means the gap only gets checked when Unity actually starts."},{"title":"History is per-user and not in version control","body":"It persists to UserSettings/, the folder Unity reserves for per-user editor state. It will not follow you to another machine and will not appear in a teammate's project."}],"seeAlso":["LevelTransformGuidance","TodoScannerWindow"]}],"groups":[{"title":"Level & Scene Tools","ids":["level-transform-guidance","bulk-hierarchy-tools-window","greybox-placer-window","greybox-block-marker","locomotion-animator-generator-window"]},{"title":"Project & Assets","ids":["batch-asset-renamer-window","find-references-window","todo-scanner-window","csv-table-window","csv-to-scriptable-object-importer","scriptable-object-table-window","player-prefs-editor-window"]},{"title":"Inspector Attributes","ids":["button-attribute","layer-attribute","read-only-attribute","tag-attribute"]},{"title":"Workflow","ids":["task-recaller"]}]};
